import{_ as a,o,c as l,ae as i}from"./chunks/framework.RRduUuAx.js";const g=JSON.parse('{"title":"iCost 明細インポート","description":"","frontmatter":{},"headers":[],"relativePath":"v1/ja/guide/08-icost-bill-import-guide.md","filePath":"v1/ja/guide/08-icost-bill-import-guide.md"}'),e={name:"v1/ja/guide/08-icost-bill-import-guide.md"};function r(d,t,s,h,n,c){return o(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="icost-明細インポート" tabindex="-1">iCost 明細インポート <a class="header-anchor" href="#icost-明細インポート" aria-label="Permalink to &quot;iCost 明細インポート&quot;">​</a></h1><h2 id="📋-概要" tabindex="-1">📋 概要 <a class="header-anchor" href="#📋-概要" aria-label="Permalink to &quot;📋 概要&quot;">​</a></h2><p>本ガイドでは、<strong>iCost</strong> から書き出した明細を <strong>Koala</strong> にインポートする手順を説明します。</p><p>Koala は現在、<strong>iCost の Excel エクスポート</strong>（<code>.xlsx</code> / <code>.xls</code>）に対応しています。<strong>iCost の CSV は非対応</strong>です。</p><hr><h2 id="📱-手順-1-icost-で明細をエクスポート" tabindex="-1">📱 手順 1：iCost で明細をエクスポート <a class="header-anchor" href="#📱-手順-1-icost-で明細をエクスポート" aria-label="Permalink to &quot;📱 手順 1：iCost で明細をエクスポート&quot;">​</a></h2><p>iCost はバージョンによってメニュー名が多少異なりますが、流れは共通です。「エクスポート/データ書き出し」から Excel 形式で保存します。</p><h3 id="手順-1-エクスポート画面を開く" tabindex="-1">手順 1：エクスポート画面を開く <a class="header-anchor" href="#手順-1-エクスポート画面を開く" aria-label="Permalink to &quot;手順 1：エクスポート画面を開く&quot;">​</a></h3><ol><li>iCost を開く</li><li><strong>設定 / もっと</strong>（または「我的」の設定）を開く</li><li><strong>导出 / 数据导出 / 导出账单</strong>（表記は異なる場合あり）を探す</li></ol><h3 id="手順-2-形式を-excel-にして保存" tabindex="-1">手順 2：形式を Excel にして保存 <a class="header-anchor" href="#手順-2-形式を-excel-にして保存" aria-label="Permalink to &quot;手順 2：形式を Excel にして保存&quot;">​</a></h3><ol><li>形式：<strong>Excel（.xlsx / .xls）</strong> を選択</li><li>期間を選択（1 回あたり 3 か月以内を推奨）</li><li>エクスポートして端末に保存（共有 → ファイルに保存 など）</li></ol><blockquote><p>⚠️ 重要：CSV で書き出すと、Koala 側で「CSV は非対応、Excel を使用してください」と表示されます。</p></blockquote><hr><h2 id="📱-手順-2-koala-にインポート" tabindex="-1">📱 手順 2：Koala にインポート <a class="header-anchor" href="#📱-手順-2-koala-にインポート" aria-label="Permalink to &quot;📱 手順 2：Koala にインポート&quot;">​</a></h2><h3 id="手順-1-インポート画面を開く" tabindex="-1">手順 1：インポート画面を開く <a class="header-anchor" href="#手順-1-インポート画面を開く" aria-label="Permalink to &quot;手順 1：インポート画面を開く&quot;">​</a></h3><ol><li>Koala を開く</li><li><strong>「設定」</strong> → <strong>「明細インポート」</strong></li></ol><h3 id="手順-2-インポート元を選択" tabindex="-1">手順 2：インポート元を選択 <a class="header-anchor" href="#手順-2-インポート元を選択" aria-label="Permalink to &quot;手順 2：インポート元を選択&quot;">​</a></h3><ol><li><strong>「インポート元」</strong> をタップ</li><li><strong>「iCost」</strong> を選択</li></ol><blockquote><p>⚠️ 重要：必ず iCost を選択してください。別のインポート元で解析すると、ヘッダーが見つからない、または列がずれて読み取られることがあります。</p></blockquote><h3 id="手順-3-ファイルを選択" tabindex="-1">手順 3：ファイルを選択 <a class="header-anchor" href="#手順-3-ファイルを選択" aria-label="Permalink to &quot;手順 3：ファイルを選択&quot;">​</a></h3><ol><li><strong>「ファイルパス」</strong> をタップ</li><li>iCost から書き出した Excel（<code>.xlsx</code> / <code>.xls</code>）を選択</li><li>ファイル名が表示されることを確認</li></ol><h3 id="手順-4-帳本-ledger-を関連付け" tabindex="-1">手順 4：帳本（Ledger）を関連付け <a class="header-anchor" href="#手順-4-帳本-ledger-を関連付け" aria-label="Permalink to &quot;手順 4：帳本（Ledger）を関連付け&quot;">​</a></h3><ol><li><strong>「関連付け帳本」</strong> をタップ</li><li>取り込み先の帳本を選択</li></ol><h3 id="手順-5-解析-→-プレビュー" tabindex="-1">手順 5：解析 → プレビュー <a class="header-anchor" href="#手順-5-解析-→-プレビュー" aria-label="Permalink to &quot;手順 5：解析 → プレビュー&quot;">​</a></h3><ol><li>右上の <strong>「解析」</strong> をタップ</li><li>成功するとプレビュー画面へ移動</li><li>プレビューでカテゴリ/口座/時間/金額/タグ/メモなどを編集してから取り込みできます</li></ol><h3 id="手順-6-インポート実行" tabindex="-1">手順 6：インポート実行 <a class="header-anchor" href="#手順-6-インポート実行" aria-label="Permalink to &quot;手順 6：インポート実行&quot;">​</a></h3><ol><li>内容を確認したら <strong>「インポート」</strong> をタップ</li><li>完了まで待つ</li></ol><hr><h2 id="📋-icost-excel-の形式-参考" tabindex="-1">📋 iCost Excel の形式（参考） <a class="header-anchor" href="#📋-icost-excel-の形式-参考" aria-label="Permalink to &quot;📋 iCost Excel の形式（参考）&quot;">​</a></h2><p>Koala の検証ポイント：</p><ul><li>読み取り可能なワークシートが存在すること</li><li>ヘッダー行に <strong>「日期」</strong> が含まれること（ヘッダー行の特定に使用）</li></ul><blockquote><p>📝 ヒント：iCost のエクスポートで言語を選べる場合、<strong>中国語ヘッダー</strong>での出力をおすすめします（少なくとも「日期」を含めてください）。</p></blockquote><h3 id="読み取り列-位置で判定" tabindex="-1">読み取り列（位置で判定） <a class="header-anchor" href="#読み取り列-位置で判定" aria-label="Permalink to &quot;読み取り列（位置で判定）&quot;">​</a></h3><p>Koala は iCost Excel の一部列を「列位置」で読み取ります。その他の列は無視されます。</p><table tabindex="0"><thead><tr><th>列</th><th>フィールド</th><th>説明</th></tr></thead><tbody><tr><td>1</td><td>日付</td><td><code>yyyy-MM-dd</code> / <code>yyyy/MM/dd</code> / <code>yyyy-MM-ddTHH:mm:ss</code> / <code>yyyy-MM-dd HH:mm:ss</code>、および Excel のシリアル日付に対応</td></tr><tr><td>2</td><td>種別</td><td>「支出」または「收入」を含む必要あり（支出/収入を判定）</td></tr><tr><td>3</td><td>金額</td><td><code>+</code> / <code>-</code> を含んでも可。取り込み時に符号を除去し、千区切り <code>,</code> も処理</td></tr><tr><td>4</td><td>親カテゴリ</td><td>Koala の親カテゴリ名と照合</td></tr><tr><td>5</td><td>子カテゴリ</td><td>空の場合は親カテゴリを使用</td></tr><tr><td>6</td><td>口座</td><td>空の場合は既定口座（デフォルト）を使用</td></tr><tr><td>8</td><td>メモ</td><td>メモ本文</td></tr><tr><td>9</td><td>通貨コード</td><td><code>CNY</code> / <code>USD</code> など。空または不一致の場合は帳本通貨を使用</td></tr><tr><td>10</td><td>タグ</td><td>複数タグはカンマ区切り（<code>,</code>）。中国語カンマ <code>，</code> も対応</td></tr></tbody></table><h3 id="koala-への取り込み-概要" tabindex="-1">Koala への取り込み（概要） <a class="header-anchor" href="#koala-への取り込み-概要" aria-label="Permalink to &quot;Koala への取り込み（概要）&quot;">​</a></h3><ul><li>日付（row[0]）→ 日付</li><li>種別（row[1]）→ 収入/支出</li><li>金額（row[2]）→ 金額</li><li>親カテゴリ（row[3]）→ 親カテゴリ（照合/作成）</li><li>子カテゴリ（row[4]、空なら親）→ 子カテゴリ（照合/作成）</li><li>口座（row[5]、空なら既定）→ 口座</li><li>7 列目（row[6]）→ 未使用（取り込み対象外）</li><li>メモ（row[7]）→ メモ</li><li>通貨コード（row[8]）→ 通貨（コードで照合。不一致は帳本通貨）</li><li>タグ（row[9]）→ タグ（照合/作成して紐付け）</li></ul><hr><h2 id="⚠️-注意事項" tabindex="-1">⚠️ 注意事項 <a class="header-anchor" href="#⚠️-注意事項" aria-label="Permalink to &quot;⚠️ 注意事項&quot;">​</a></h2><ol><li><strong>Excel のみ対応</strong>：iCost の CSV は取り込めません。</li><li><strong>自動重複排除なし</strong>：同じファイルを二重に取り込むと重複明細が作成されます。取り込み範囲の重複に注意してください。</li><li><strong>ヘッダー言語</strong>：「日期」を含む行をヘッダーとして探すため、英語ヘッダー等だとヘッダーが見つからず失敗することがあります。</li><li><strong>口座が空の場合</strong>：「口座」列が空だと既定口座に入ります。プレビューでまとめて口座を編集するか、iCost 側で口座を補完してから再書き出ししてください。</li><li><strong>カテゴリ一致</strong>：親 + 子の名称で一致させます。未一致の場合はプレビューで修正してから取り込んでください。</li></ol><hr><h2 id="🔧-よくある質問" tabindex="-1">🔧 よくある質問 <a class="header-anchor" href="#🔧-よくある質問" aria-label="Permalink to &quot;🔧 よくある質問&quot;">​</a></h2><h3 id="q1-「icost-のヘッダーが見つからない」と表示されます" tabindex="-1">Q1：「iCost のヘッダーが見つからない」と表示されます <a class="header-anchor" href="#q1-「icost-のヘッダーが見つからない」と表示されます" aria-label="Permalink to &quot;Q1：「iCost のヘッダーが見つからない」と表示されます&quot;">​</a></h3><p>主な原因：</p><ol><li>ヘッダー行に「日期」が含まれていない（英語ヘッダーなど）</li><li>iCost のファイルではない、または編集して構造が崩れている</li><li>Excel が空、またはワークシートがない</li></ol><p>iCost から再エクスポートし、中国語ヘッダーを優先してください。</p><h3 id="q2-口座が空で、全部同じ口座に入ってしまいました" tabindex="-1">Q2：口座が空で、全部同じ口座に入ってしまいました <a class="header-anchor" href="#q2-口座が空で、全部同じ口座に入ってしまいました" aria-label="Permalink to &quot;Q2：口座が空で、全部同じ口座に入ってしまいました&quot;">​</a></h3><p>「口座」列が空の場合の既定動作です。プレビューでまとめて口座を編集するか、iCost 側で口座を補完してから再インポートしてください。</p><h3 id="q3-カテゴリが一致しません" tabindex="-1">Q3：カテゴリが一致しません <a class="header-anchor" href="#q3-カテゴリが一致しません" aria-label="Permalink to &quot;Q3：カテゴリが一致しません&quot;">​</a></h3><p>プレビューで 1 件ずつ正しいカテゴリを選択してください。もしくは Koala 側に iCost と同名のカテゴリを事前に作成してから再解析してください。</p><hr><h2 id="📚-関連ガイド" tabindex="-1">📚 関連ガイド <a class="header-anchor" href="#📚-関連ガイド" aria-label="Permalink to &quot;📚 関連ガイド&quot;">​</a></h2><ul><li><a href="./01-template-bill-import-guide">テンプレート明細インポート（CSV）</a></li><li><a href="./02-wechat-bill-import-guide">WeChat 明細インポート</a></li><li><a href="./03-alipay-bill-import-guide">Alipay 明細インポート</a></li><li><a href="./07-pixiu-bill-import-guide">Pixiu 明細インポート</a></li><li><a href="./04-multi-ledger-guide">複数帳簿（多帳本）</a></li></ul><hr><p><strong>最終更新</strong>：2026 年 4 月</p>',55)])])}const b=a(e,[["render",r]]);export{g as __pageData,b as default};
